/* Mây Học Tin: hoạt động "Thử ngay" trong bài học, báo cáo, giấy khen, hồ sơ. Nạp trước app.js; mọi hàm chỉ chạy sau khi app.js đã sẵn sàng. */

/* ============ HOẠT ĐỘNG TRONG BÀI HỌC ============ */
const LS={};const ls=(k,d)=>LS[k]||(LS[k]=d);
const lb=(w,v,label,cls,dis)=>`<button class="chip ${cls||''}" data-act="lw" data-w="${w}" data-v="${v}" ${dis?'disabled':''}>${label}</button>`;
const LWR={},LWA={};
/* chủ đề → số thứ tự bài (từ 0) → hoạt động */
const LW={mt:{1:'io',2:'ram',4:'units'},hdh:{2:'tree',4:'bin',5:'win'},pm:{4:'clip'},vb:{0:'del',1:'fmt'},bt:{3:'calc',5:'chart',8:'fill'},ct:{1:'perm',4:'meet'},cd:{3:'post'},tc:{3:'anim'},net:{2:'url'},gt:{1:'mail'},at:{1:'pw',2:'phish'}};
const LWSTATIC={units:1};
function lwFrame(id,k){const key=(LW[id]||{})[k];if(!key||!LWR[key])return '';return `<div class="try"><div class="qtype">${LWSTATIC[key]?t('Hình minh hoạ','Picture'):t('Thử ngay','Try it')}</div><div id="lw-${key}" class="lwbody">${LWR[key]()}</div></div>`}
function drawW(key){const el=document.getElementById('lw-'+key);if(el)el.innerHTML=LWR[key]()}

const DEV=[['Bàn phím','Keyboard',0,'Em gõ, chữ đi vào máy.','You type and the letters go in.'],['Chuột','Mouse',0,'Em bấm, lệnh đi vào máy.','You click and the command goes in.'],['Micro','Microphone',0,'Em nói, âm thanh đi vào máy.','You speak and the sound goes in.'],['Máy quét','Scanner',0,'Hình trên giấy đi vào máy.','A picture on paper goes in.'],['Màn hình','Monitor',1,'Máy cho em xem hình và chữ.','The computer shows you pictures and text.'],['Loa','Speakers',1,'Máy phát âm thanh cho em nghe.','The computer plays sound for you.'],['Máy in','Printer',1,'Máy đưa bài ra giấy.','The computer puts your work on paper.'],['Màn hình cảm ứng','Touchscreen',2,'Em chạm để ra lệnh và nhìn để xem kết quả.','You touch to give orders and look to see results.']];
LWR.io=()=>{const s=ls('io',{i:-1}),d=DEV[s.i],pc=`<span class="node pc">${t('Máy tính','Computer')}</span>`;
 return `<p>${t('Chạm vào một thiết bị để xem thông tin đi theo hướng nào.','Tap a device to see which way the information travels.')}</p><div class="chips">${DEV.map((x,i)=>lb('io',i,t(x[0],x[1]),s.i===i?'sel':'')).join('')}</div>`+(d?`<div class="flow">${d[2]===1?pc+'<b>→</b>':''}<span class="node">${t(d[0],d[1])}</span>${d[2]===0?'<b>→</b>'+pc:d[2]===2?'<b>⇄</b>'+pc:''}<span class="pill ${d[2]===2?'warn':d[2]?'ok':''}">${[t('Thiết bị vào','Input device'),t('Thiết bị ra','Output device'),t('Cả vào và ra','Both input and output')][d[2]]}</span></div><p class="msg">${t(d[3],d[4])}</p>`:'')};
LWA.io=v=>{ls('io',{i:-1}).i=+v};

LWR.ram=()=>{const s=ls('ram',{ram:1,disk:0,m:0}),doc=`<span class="doc">${t('Bài văn của em','Your essay')}</span>`;
 const msgs=[t('Em đang gõ bài. Bài mới chỉ nằm trong RAM.','You are typing. So far the essay is only in RAM.'),t('Đã lưu. Bài có thêm một bản trong ổ cứng.','Saved. There is now a copy on the hard drive.'),t('Tắt máy: RAM quên sạch. Bài vẫn còn trong ổ cứng, mở lại là có.','Power off: RAM forgot everything. The essay is still on the hard drive, so you can open it again.'),t('Ôi! Tắt máy khi chưa lưu nên bài mất rồi. Lần sau nhớ nhấn Ctrl + S nhé.','Oh no! The power went off before saving, so the essay is gone. Press Ctrl + S next time.'),t('Bài được nạp từ ổ cứng vào RAM để em làm tiếp.','The essay is loaded from the hard drive back into RAM so you can carry on.')];
 return `<div class="boxes"><div class="box"><h4>RAM · ${t('trí nhớ tạm','short-term memory')}</h4>${s.ram?doc:''}</div><div class="box"><h4>${t('Ổ cứng · trí nhớ lâu dài','Hard drive · long-term memory')}</h4>${s.disk?doc:''}</div></div><p class="msg">${msgs[s.m]}</p><div class="chips">${lb('ram','type',t('Gõ bài mới','Type a new essay'))}${lb('ram','save',t('Lưu (Ctrl + S)','Save (Ctrl + S)'),'',!s.ram)}${lb('ram','off',t('Tắt máy rồi bật lại','Turn off and on again'))}${lb('ram','open',t('Mở lại bài','Open the essay'),'',!s.disk||s.ram)}</div>`};
LWA.ram=v=>{const s=ls('ram',{ram:1,disk:0,m:0});if(v==='type'){s.ram=1;s.disk=0;s.m=0}if(v==='save'&&s.ram){s.disk=1;s.m=1}if(v==='off'){s.ram=0;s.m=s.disk?2:3}if(v==='open'&&s.disk){s.ram=1;s.m=4}};

LWR.units=()=>`<div class="units">${[['Byte',6,t('1 chữ cái','1 letter')],['KB',26,t('1 trang chữ','1 page of text')],['MB',50,t('1 bức ảnh','1 photo')],['GB',76,t('1 bộ phim','1 film')],['TB',100,t('Cả một thư viện phim','A whole film library')]].map(u=>`<div class="urow"><b>${u[0]}</b><div class="tbar"><i style="width:${u[1]}%"></i></div><span>${u[2]}</span></div>`).join('')}</div><p class="muted">${t('Thanh chỉ để so sánh thứ tự. Thật ra mỗi bậc lớn hơn bậc trước khoảng 1000 lần.','The bars only show the order. Each step is really about 1000 times bigger than the one before.')}</p>`;

const TREE=['d','Học tập','School work',[['d','Tin học','Computing',[['f','bai-tap.docx'],['f','bang-diem.xlsx'],['f','thuyet-trinh.pptx']]],['d','Mỹ thuật','Art',[['f','tranh-ve.png'],['f','anh-lop.jpg']]],['f','thoi-khoa-bieu.pdf']]];
const EXT={docx:['tệp văn bản, mở bằng Word','a text document, opened with Word'],xlsx:['tệp bảng tính, mở bằng Excel','a spreadsheet, opened with Excel'],pptx:['tệp trình chiếu, mở bằng PowerPoint','a presentation, opened with PowerPoint'],png:['tệp hình ảnh','a picture file'],jpg:['tệp hình ảnh','a picture file'],pdf:['tài liệu để đọc','a document for reading']};
const FOLD='<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',FILEI='<path d="M6 3h9l4 4v14H6z"/><path d="M15 3v4h4"/>';
function treeH(n,id,s){if(n[0]==='f')return `<li><button class="${s.f===n[1]?'on':''}" data-act="lw" data-w="tree" data-v="f:${n[1]}">${ic(FILEI)}<span>${n[1]}</span></button></li>`;
 const op=s.open[id];return `<li><button data-act="lw" data-w="tree" data-v="d:${id}" aria-expanded="${!!op}">${ic(FOLD)}<b>${t(n[1],n[2])}</b><span class="muted">${op?t('đang mở','open'):t('bấm để mở','tap to open')}</span></button>${op?`<ul class="tree">${n[3].map((c,i)=>treeH(c,id+'-'+i,s)).join('')}</ul>`:''}</li>`}
LWR.tree=()=>{const s=ls('tree',{open:{0:1},f:''}),e=s.f&&EXT[s.f.split('.').pop()];
 return `<p>${t('Bấm vào thư mục để mở, bấm vào tệp để xem nó thuộc loại gì.','Tap a folder to open it. Tap a file to see what kind it is.')}</p><ul class="tree root">${treeH(TREE,'0',s)}</ul>${e?`<p class="msg"><kbd>${s.f}</kbd> ${t('là '+e[0],'is '+e[1])}.</p>`:''}`};
LWA.tree=v=>{const s=ls('tree',{open:{0:1},f:''});if(v[0]==='d'){const id=v.slice(2);s.open[id]=!s.open[id]}else s.f=v.slice(2)};

const F3=['bai-van.docx','anh-meo.jpg','bai-hat.mp3'];
LWR.bin=()=>{const s=ls('bin',{desk:[0,1,2],bin:[]});const row=(i,a,lab)=>`<div class="frow"><span class="doc">${F3[i]}</span><button class="chip sm" data-act="lw" data-w="bin" data-v="${a}:${i}">${lab}</button></div>`;
 return `<div class="boxes"><div class="box"><h4>Desktop · ${t('màn hình nền','your files')}</h4>${s.desk.map(i=>row(i,'del','Delete')).join('')||`<span class="muted">${t('Trống','Empty')}</span>`}</div><div class="box"><h4>Recycle Bin · ${t('Thùng rác','deleted files')}</h4>${s.bin.map(i=>row(i,'res','Restore')).join('')||`<span class="muted">${t('Trống','Empty')}</span>`}</div></div><p class="msg">${s.bin.length?t('Tệp bị xoá chưa mất hẳn. Bấm Restore để đưa về chỗ cũ.','A deleted file is not gone yet. Press Restore to put it back.'):t('Bấm Delete để xoá thử một tệp.','Press Delete to remove a file.')}</p>`};
LWA.bin=v=>{const [a,i]=v.split(':'),s=ls('bin',{desk:[0,1,2],bin:[]}),from=a==='del'?s.desk:s.bin,to=a==='del'?s.bin:s.desk,k=from.indexOf(+i);if(k>=0){from.splice(k,1);to.push(+i)}};

LWR.win=()=>{const s=ls('win',{m:'n'}),wbtn=(v,ch,lab)=>`<button data-act="lw" data-w="win" data-v="${v}" aria-label="${lab}">${ch}</button>`;
 const say={n:t('Bấm thử ba nút ở góc trên bên phải cửa sổ.','Try the three buttons at the top right of the window.'),min:t('Thu nhỏ: cửa sổ nằm xuống thanh tác vụ, chương trình vẫn chạy. Bấm Paint trên thanh tác vụ để mở lại.','Minimized: the window rests on the taskbar and the program keeps running. Click Paint on the taskbar to bring it back.'),max:t('Phóng to: cửa sổ rộng hết màn hình. Bấm nút □ lần nữa để về cỡ cũ.','Maximized: the window fills the screen. Click □ again to go back to the old size.'),x:t('Đóng: chương trình đã tắt hẳn.','Closed: the program has stopped.')}[s.m];
 const w=s.m==='n'||s.m==='max'?`<div class="mwin ${s.m==='max'?'max':''}"><div class="mbar"><span>Paint</span><span>${wbtn('min','–','Minimize')}${wbtn(s.m==='max'?'n':'max','□','Maximize')}${wbtn('x','×','Close')}</span></div><div class="mbody">${t('Bức tranh của em','Your drawing')}</div></div>`:'<div></div>';
 return `<div class="desk">${w}<div class="tbr"><span>Start</span>${s.m==='x'?'':`<button data-act="lw" data-w="win" data-v="n">Paint</button>`}</div></div><p class="msg">${say}</p>${s.m==='x'?`<div class="chips">${lb('win','n',t('Mở lại Paint','Open Paint again'))}</div>`:''}`};
LWA.win=v=>{ls('win',{m:'n'}).m=v};

LWR.clip=()=>{const s=ls('clip',{src:1,cb:0,dst:0,m:0}),w='<span class="doc">Mây</span>';
 const ms=[t('Chữ “Mây” đang được chọn. Thử Sao chép hoặc Cắt.','The word “Mây” is selected. Try Copy or Cut.'),t('Sao chép: chữ vẫn ở chỗ cũ, và có một bản trong bộ nhớ tạm.','Copy: the word stays where it was, and a copy waits on the clipboard.'),t('Cắt: chữ rời chỗ cũ và nằm chờ trong bộ nhớ tạm.','Cut: the word leaves its place and waits on the clipboard.'),t('Dán: chữ từ bộ nhớ tạm hiện ra ở chỗ mới. Em dán được nhiều lần.','Paste: the word from the clipboard appears in the new place. You can paste many times.'),t('Bộ nhớ tạm đang trống. Em cần Sao chép hoặc Cắt trước.','The clipboard is empty. Copy or cut first.')];
 return `<div class="boxes"><div class="box"><h4>${t('Chỗ cũ','Old place')}</h4>${s.src?w:''}</div><div class="box"><h4>${t('Bộ nhớ tạm','Clipboard')}</h4>${s.cb?w:''}</div><div class="box"><h4>${t('Chỗ mới','New place')}</h4>${w.repeat(s.dst)}</div></div><p class="msg">${ms[s.m]}</p><div class="chips">${lb('clip','c',t('Sao chép (Ctrl + C)','Copy (Ctrl + C)'),'',!s.src)}${lb('clip','x',t('Cắt (Ctrl + X)','Cut (Ctrl + X)'),'',!s.src)}${lb('clip','v',t('Dán (Ctrl + V)','Paste (Ctrl + V)'))}${lb('clip','r',t('Làm lại','Reset'))}</div>`};
LWA.clip=v=>{const s=ls('clip',{src:1,cb:0,dst:0,m:0});if(v==='c'&&s.src){s.cb=1;s.m=1}if(v==='x'&&s.src){s.src=0;s.cb=1;s.m=2}if(v==='v'){if(s.cb){s.dst=Math.min(s.dst+1,6);s.m=3}else s.m=4}if(v==='r')LS.clip={src:1,cb:0,dst:0,m:0}};

LWR.del=()=>{const s=ls('del',{t:'MAYTINH',p:3});return `<p>${t('Vạch đỏ là con trỏ. Thử hai phím xoá và xem chữ nào biến mất.','The red bar is the cursor. Try both delete keys and watch which letter disappears.')}</p><div class="delt">${esc(s.t.slice(0,s.p))}<span class="cur"></span>${esc(s.t.slice(s.p))}</div><div class="chips">${lb('del','b','← Backspace','',s.p<1)}${lb('del','d','Delete →','',s.p>=s.t.length)}${lb('del','l',t('Con trỏ sang trái','Cursor left'),'',s.p<1)}${lb('del','r',t('Con trỏ sang phải','Cursor right'),'',s.p>=s.t.length)}${lb('del','0',t('Làm lại','Reset'))}</div>`};
LWA.del=v=>{const s=ls('del',{t:'MAYTINH',p:3});if(v==='b'&&s.p>0){s.t=s.t.slice(0,s.p-1)+s.t.slice(s.p);s.p--}if(v==='d'&&s.p<s.t.length)s.t=s.t.slice(0,s.p)+s.t.slice(s.p+1);if(v==='l'&&s.p>0)s.p--;if(v==='r'&&s.p<s.t.length)s.p++;if(v==='0')LS.del={t:'MAYTINH',p:3}};

const wbi=id=>WB.find(b=>b&&b[0]===id)[3];
LWR.fmt=()=>{const s=ls('fmt',{b:0,i:0,u:0,al:'left',sz:22}),tb=(v,inner,on,lab)=>`<button class="tb ${on?'sel':''}" data-act="lw" data-w="fmt" data-v="${v}" aria-label="${lab}">${inner}</button>`;
 return `<p>${t('Bấm các nút và xem dòng chữ thay đổi.','Press the buttons and watch the line of text change.')}</p><div class="wordui">${tb('b','B',s.b,'Bold')}${tb('i','<i>I</i>',s.i,'Italic')}${tb('u','<u>U</u>',s.u,'Underline')}<span class="sep"></span>${tb('left',ic(wbi('alignL')),s.al==='left','Left')}${tb('center',ic(wbi('alignC')),s.al==='center','Center')}${tb('right',ic(wbi('alignR')),s.al==='right','Right')}<span class="sep"></span>${tb('-','A−',0,'Smaller')}${tb('+','A+',0,'Bigger')}</div><div class="pv" style="font-weight:${s.b?800:400};font-style:${s.i?'italic':'normal'};text-decoration:${s.u?'underline':'none'};text-align:${s.al};font-size:${s.sz}px">${t('Em yêu Tin học','I love computing')}</div>`};
LWA.fmt=v=>{const s=ls('fmt',{b:0,i:0,u:0,al:'left',sz:22});if(v==='b'||v==='i'||v==='u')s[v]=!s[v];else if(v==='+')s.sz=Math.min(38,s.sz+4);else if(v==='-')s.sz=Math.max(14,s.sz-4);else s.al=v};

const FML=[['=SUM(A1:A3)',v=>v[0]+v[1]+v[2]],['=AVERAGE(A1:A3)',v=>(v[0]+v[1]+v[2])/3],['=MAX(A1:A3)',v=>Math.max(...v)],['=MIN(A1:A3)',v=>Math.min(...v)],['=A1+A2*A3',v=>v[0]+v[1]*v[2]]];
const calcOut=()=>{const s=ls('calc',{v:[2,3,5],f:0});return Math.round(FML[s.f][1](s.v)*100)/100};
LWR.calc=()=>{const s=ls('calc',{v:[2,3,5],f:0});return `<p>${t('Đổi số trong ba ô, rồi chọn công thức cho ô A4.','Change the numbers in the three cells, then pick a formula for cell A4.')}</p><div class="sim"><table class="xl"><tr><th></th><th>A</th></tr>${s.v.map((x,i)=>`<tr><th>${i+1}</th><td><input class="cellin lw-calc" data-i="${i}" id="calc-${i}" type="number" inputmode="decimal" value="${x}" aria-label="A${i+1}"></td></tr>`).join('')}<tr><th>4</th><td><span class="cell hl" id="calc-out">${calcOut()}</span></td></tr></table></div><div class="chips">${FML.map((f,i)=>lb('calc',i,f[0],s.f===i?'sel':'')).join('')}</div><p class="msg">${t('Ô A4 đang chứa công thức','Cell A4 holds the formula')} <kbd>${FML[s.f][0]}</kbd></p>`};
LWA.calc=v=>{ls('calc',{v:[2,3,5],f:0}).f=+v};

const C4=['#1766d1','#14885a','#d9601a','#7a3fe0'],CD=[3,5,4,8];
LWR.chart=()=>{const s=ls('chart',{k:'col'}),wk=i=>t('T','W')+(i+1);let g='';
 if(s.k==='col')g=CD.map((v,i)=>`<rect x="${34+i*56}" y="${126-v*13}" width="36" height="${v*13}" rx="4" fill="${C4[i]}"/><text x="${52+i*56}" y="${120-v*13}" text-anchor="middle">${v}</text><text x="${52+i*56}" y="143" text-anchor="middle">${wk(i)}</text>`).join('')+'<path d="M22 126h228" stroke="currentColor"/>';
 if(s.k==='line')g=`<path d="M22 126h228" stroke="currentColor"/><polyline fill="none" stroke="${C4[0]}" stroke-width="3" points="${CD.map((v,i)=>(52+i*56)+','+(126-v*13)).join(' ')}"/>`+CD.map((v,i)=>`<circle cx="${52+i*56}" cy="${126-v*13}" r="5" fill="${C4[0]}"/><text x="${52+i*56}" y="${114-v*13}" text-anchor="middle">${v}</text><text x="${52+i*56}" y="143" text-anchor="middle">${wk(i)}</text>`).join('');
 if(s.k==='pie'){let a=-Math.PI/2;const tot=CD.reduce((x,y)=>x+y,0);g=CD.map((v,i)=>{const b=a+v/tot*2*Math.PI,p=`<path d="M75 75L${(75+60*Math.cos(a)).toFixed(1)} ${(75+60*Math.sin(a)).toFixed(1)}A60 60 0 ${v/tot>.5?1:0} 1 ${(75+60*Math.cos(b)).toFixed(1)} ${(75+60*Math.sin(b)).toFixed(1)}Z" fill="${C4[i]}" stroke="#fff" stroke-width="2"/><rect x="160" y="${28+i*26}" width="14" height="14" rx="3" fill="${C4[i]}"/><text x="182" y="${40+i*26}">${wk(i)}: ${v}</text>`;a=b;return p}).join('')}
 const say={col:t('Biểu đồ cột: dễ so sánh tuần nào đọc nhiều sách nhất.','Column chart: easy to compare which week had the most books.'),line:t('Biểu đồ đường: thấy rõ số sách tăng hay giảm qua các tuần.','Line chart: shows clearly whether the number went up or down over the weeks.'),pie:t('Biểu đồ tròn: mỗi tuần chiếm bao nhiêu phần trong tổng 20 cuốn.','Pie chart: how big a share each week has of all 20 books.')}[s.k];
 return `<p>${t('Cùng một số liệu: số sách em đọc trong 4 tuần. Chọn kiểu biểu đồ.','The same data: books you read over 4 weeks. Pick a chart type.')}</p><div class="chips">${lb('chart','col',t('Cột','Column'),s.k==='col'?'sel':'')}${lb('chart','line',t('Đường','Line'),s.k==='line'?'sel':'')}${lb('chart','pie',t('Tròn','Pie'),s.k==='pie'?'sel':'')}</div><svg class="chartsvg" viewBox="0 0 260 150" role="img" aria-label="${say}">${g}</svg><p class="msg">${say}</p>`};
LWA.chart=v=>{ls('chart',{k:'col'}).k=v};

LWR.anim=()=>{const s=ls('anim',{r:''});return `<div class="stage"><div class="sl s1 ${s.r==='tr'?'out':''}"><b>Slide 1</b><span class="${s.r==='an'?'fly':''}">${t('Xin chào các bạn!','Hello everyone!')}</span></div>${s.r==='tr'?`<div class="sl s2 in"><b>Slide 2</b><span>${t('Loài vật em yêu thích','My favourite animal')}</span></div>`:''}</div><div class="chips">${lb('anim','tr',t('Chạy Transition','Play a transition'))}${lb('anim','an',t('Chạy Animation','Play an animation'))}</div><p class="msg">${s.r==='tr'?t('Transition: cả Slide 1 trượt đi và Slide 2 trượt vào.','Transition: the whole of Slide 1 slides away and Slide 2 slides in.'):s.r==='an'?t('Animation: slide đứng yên, chỉ dòng chữ bay vào.','Animation: the slide stays still and only the line of text flies in.'):t('Bấm từng nút để thấy hai loại hiệu ứng khác nhau thế nào.','Press each button to see how the two effects differ.')}</p>`};
LWA.anim=v=>{ls('anim',{r:''}).r=v};

function partsW(key,intro,items,mono){const s=ls(key,{i:-1});return `<p>${intro}</p><div class="${mono?'urlrow':'chips'}">${items.map((x,i)=>`<button class="${mono?'upart':'chip'} ${s.i===i?'sel':''}" data-act="lw" data-w="${key}" data-v="${i}">${x[0]}</button>`).join('')}</div>${s.i>=0?`<p class="msg">${items[s.i][1]}</p>`:''}`}
LWR.url=()=>partsW('url',t('Bấm vào từng phần của địa chỉ web để xem nó nói gì.','Click each part of the web address to see what it tells you.'),[['https://',t('Cách kết nối. Chữ s nghĩa là bảo mật, đi kèm hình ổ khoá.','How you connect. The s means secure and comes with a padlock.')],['www.moet',t('Tên của trang web. Đây là trang của Bộ Giáo dục và Đào tạo.','The name of the site. This one belongs to the Ministry of Education and Training.')],['.gov',t('Loại tổ chức: cơ quan nhà nước.','The kind of organization: government.')],['.vn',t('Quốc gia: Việt Nam.','The country: Vietnam.')]],true);
LWA.url=v=>{ls('url',{i:-1}).i=+v};
LWR.mail=()=>partsW('mail',t('Bấm vào từng phần của một bức thư điện tử.','Click each part of an email.'),[['To',t('Người nhận chính. Em gõ địa chỉ email của họ vào đây.','The main receiver. Type their email address here.')],['Cc',t('Người được gửi thêm một bản để cùng biết. Mọi người đều thấy địa chỉ này.','Someone who gets a copy so they know too. Everyone can see this address.')],['Bcc',t('Người nhận ẩn. Những người khác không thấy địa chỉ này.','A hidden receiver. The others cannot see this address.')],['Subject',t('Tiêu đề thư, viết ngắn gọn để người nhận biết thư nói về gì.','The title, kept short so the receiver knows what the message is about.')],[t('Kẹp giấy','Paperclip'),t('Đính kèm tệp như ảnh hoặc bài làm.','Attach a file such as a photo or your work.')],['Send',t('Gửi thư đi. Đọc lại một lượt trước khi bấm.','Send the message. Read it through once before you click.')]]);
LWA.mail=v=>{ls('mail',{i:-1}).i=+v};

function pwOut(p){const c=[p.length>=8,/[A-Z]/.test(p),/[a-z]/.test(p),/\d/.test(p),/[^A-Za-z0-9]/.test(p)],n=c.filter(Boolean).length;
 const names=en()?['8+ characters','Capital letter','Small letter','Number','Symbol']:['Từ 8 ký tự','Chữ hoa','Chữ thường','Chữ số','Ký hiệu'];
 const lv=!p?t('Gõ thử một mật khẩu tự nghĩ ra.','Type a made-up password.'):n>=5?t('Rất mạnh. Mật khẩu kiểu này khó đoán.','Very strong. A password like this is hard to guess.'):n>=3?t('Tạm được. Thêm những phần còn thiếu để mạnh hơn.','Not bad. Add the missing parts to make it stronger.'):t('Yếu. Người khác dễ đoán ra.','Weak. Other people could guess it easily.');
 return `<div class="meter"><i style="width:${n*20}%;background:var(--${n>=5?'ok':n>=3?'sun':'bad'})"></i></div><p class="msg">${lv}</p><div class="chips">${names.map((x,i)=>`<span class="pill ${c[i]?'ok':'none'}">${x}</span>`).join('')}</div>`}
LWR.pw=()=>`<p>${t('Gõ một mật khẩu <b>tự nghĩ ra để thử</b>. Đừng gõ mật khẩu thật của em. Trang không lưu lại những gì em gõ ở đây.','Type a <b>made-up password to test</b>. Do not type your real password. Nothing you type here is saved.')}</p><input class="field lw-pw" id="pw-in" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="${t('Ví dụ: Meo@2024Xanh','For example: Cat@2024Blue')}"><div id="pw-out" class="lwbody">${pwOut('')}</div>`;

const PH=[['Chào bạn,','Hi there,',0,'Lời chào thì bình thường.','A greeting is normal.'],['GẤP! Chỉ còn 10 phút.','URGENT! Only 10 minutes left.',1,'Giục thật gấp để em không kịp nghĩ hay hỏi người lớn.','It rushes you so you have no time to think or ask an adult.'],['Bạn đã trúng một chiếc điện thoại miễn phí.','You have won a free phone.',1,'Quà rất lớn dù em không tham gia gì: đáng ngờ.','A big prize for a contest you never entered: suspicious.'],['Hãy gửi mật khẩu của bạn','Send your password',1,'Không ai tặng quà thật mà lại xin mật khẩu.','Nobody gives a real prize in exchange for a password.'],['tại www.qua-tang-mien-phi.xyz','at www.free-gift-for-you.xyz',1,'Đường link lạ, không phải trang em biết.','A strange link, not a site you know.'],['Chúc bạn một ngày vui.','Have a nice day.',0,'Câu chúc thì bình thường.','A kind wish is normal.']];
LWR.phish=()=>{const s=ls('phish',{f:{},last:-1}),n=PH.filter((p,i)=>p[2]&&s.f[i]).length,p=PH[s.last];
 return `<p>${t('Tin nhắn này có 4 dấu hiệu lừa đảo. Bấm vào những chỗ em thấy đáng ngờ.','This message has 4 signs of a scam. Tap the parts that look suspicious.')}</p><div class="sms">${PH.map((x,i)=>`<button class="seg1 ${s.f[i]?(x[2]?'f':'n'):''}" data-act="lw" data-w="phish" data-v="${i}">${t(x[0],x[1])}</button>`).join(' ')}</div>${p?`<p class="msg">${p[2]?t('Đúng rồi! ','Yes! '):t('Chỗ này không sao. ','This part is fine. ')}${t(p[3],p[4])}</p>`:''}<p><span class="pill ${n>=4?'ok':'warn'}">${t(`Đã tìm ${n}/4 dấu hiệu`,`${n} of 4 signs found`)}</span> ${n>=4?t('Giỏi lắm. Gặp tin nhắn thế này: không bấm, không trả lời, báo người lớn.','Well done. With a message like this: do not click, do not reply, tell an adult.'):''}</p>`};
LWA.phish=v=>{const s=ls('phish',{f:{},last:-1});s.f[+v]=1;s.last=+v};

/* ============ HỒ SƠ + MÃ CHUYỂN MÁY ============ */
const PF={del:false,code:'',msg:'',ok:false};
const pName=(p,i)=>p.name?esc(p.name):t('Bạn nhỏ','Friend')+' '+(i+1);
function setProfile(id){DB.cur=id;S=DB.profiles[id];W=null;TY={lv:0};PF.del=false;PF.code='';save()}
function addProfile(){const id='p'+Date.now();DB.profiles[id]=Object.assign(FRESH(),{lang:S.lang});setProfile(id);return id}
function delProfile(){const ids=Object.keys(DB.profiles);if(ids.length<2)return;delete DB.profiles[DB.cur];setProfile(Object.keys(DB.profiles)[0])}
const PKEYS=['level','done','name','best','read','wrong','exams','typing','days','maxStreak','fixed','badges','doneDate','tstar','lang','skin','sfx','keys','song','okSnd'];
function makeCode(){const o={};PKEYS.forEach(k=>o[k]=S[k]);return 'MHT1.'+btoa(unescape(encodeURIComponent(JSON.stringify(o))))}
function readCode(str){try{str=String(str).replace(/\s+/g,'');if(str.indexOf('MHT1.')!==0)return null;const o=JSON.parse(decodeURIComponent(escape(atob(str.slice(5)))));if(!o||typeof o!=='object')return null;
 const p=FRESH(),num=x=>typeof x==='number'&&isFinite(x);
 if(typeof o.name==='string')p.name=o.name.slice(0,20);
 TOPICS.forEach(x=>[1,2,3].forEach(l=>{const k=bk(x.id,l);if(o.best&&num(o.best[k]))p.best[k]=Math.max(0,Math.min(100,Math.round(o.best[k])));if(o.read&&o.read[k])p.read[k]=1}));
 if(o.level===2||o.level===3)p.level=o.level;if(o.done&&typeof o.done==='object')[1,2,3].forEach(l=>{if(typeof o.done[l]==='string')p.done[l]=o.done[l].slice(0,12)});
 if(Array.isArray(o.exams))o.exams.forEach(e=>{if(e&&(e.lv===2||e.lv===3))e._lv=e.lv});
 if(Array.isArray(o.wrong))p.wrong=[...new Set(o.wrong.filter(i=>Number.isInteger(i)&&i>=0&&i<Q.length))];
 if(Array.isArray(o.exams))p.exams=o.exams.filter(e=>e&&num(e.n)&&num(e.ok)&&num(e.score)).slice(0,10).map(e=>({d:String(e.d||'').slice(0,12),n:e.n,ok:e.ok,score:Math.max(0,Math.min(1000,Math.round(e.score))),lv:e.lv===2||e.lv===3?e.lv:1}));
 if(o.typing&&typeof o.typing==='object')Object.keys(o.typing).forEach(k=>{if(/^\d{1,2}$/.test(k)&&num(o.typing[k]))p.typing[k]=Math.round(o.typing[k])});
 if(o.tstar&&typeof o.tstar==='object')Object.keys(o.tstar).forEach(k=>{if(/^\d{1,2}$/.test(k)&&num(o.tstar[k]))p.tstar[k]=Math.max(0,Math.min(3,Math.round(o.tstar[k])))});
 if(Array.isArray(o.days))p.days=o.days.filter(d=>/^\d{4}-\d\d-\d\d$/.test(d)).slice(-120);
 if(num(o.maxStreak))p.maxStreak=Math.round(o.maxStreak);if(num(o.fixed))p.fixed=Math.round(o.fixed);
 if(Array.isArray(o.badges))p.badges=o.badges.filter(b=>BADGES.some(x=>x[0]===b));
 if(typeof o.doneDate==='string')p.doneDate=o.doneDate.slice(0,12);
 if(o.lang==='en')p.lang='en';if(SKINS.some(s=>s[0]===o.skin))p.skin=o.skin;p.sfx=o.sfx!==false;if(KEYMODES.some(k=>k[0]===o.keys))p.keys=o.keys;if(SONGN[o.song])p.song=o.song;if(o.okSnd==='coin')p.okSnd='coin';
 return p}catch(e){return null}}
function useCode(str){PF.ok=false;if(Object.keys(DB.profiles).length>=6)return t('Máy này đã có 6 hồ sơ. Xoá bớt một hồ sơ rồi nhập lại.','This device already has 6 profiles. Delete one, then try again.');
 const p=readCode(str);if(!p)return t('Mã chưa đúng. Em sao chép lại toàn bộ mã, bắt đầu bằng MHT1.','That code is not right. Copy the whole code again, starting with MHT1.');
 const id='p'+Date.now();DB.profiles[id]=p;setProfile(id);PF.ok=true;return ''}
function profH(){const ids=Object.keys(DB.profiles);
 return `<p class="muted">${t('Mỗi bạn một hồ sơ riêng trên máy này: tên, tiến độ, màu và âm thanh.','Each child has their own profile on this device: name, progress, colours and sounds.')}</p>
 <div class="chips">${ids.map((id,i)=>`<button class="chip ${id===DB.cur?'sel':''}" data-act="prof" data-v="${id}">${pName(DB.profiles[id],i)}</button>`).join('')}${ids.length<6?`<button class="chip" data-act="profadd">+ ${t('Thêm bạn mới','Add a child')}</button>`:''}</div>
 <label class="namebox" for="name-set"><span class="lbl">${t('Tên của hồ sơ này','Name for this profile')}</span> <input id="name-set" class="field name-in" maxlength="20" value="${esc(S.name)}" placeholder="${t('Gõ tên em vào đây','Type your name here')}" autocomplete="off"></label>
 ${ids.length>1?`<div class="row"><button class="linkbtn" data-act="profdel">${PF.del?t('Bấm lần nữa để xoá hẳn hồ sơ này','Click again to delete this profile for good'):t('Xoá hồ sơ này','Delete this profile')}</button></div>`:''}
 <h3>${t('Chuyển tiến độ sang máy khác','Move progress to another device')}</h3>
 <p class="muted">${t('Tạo mã ở máy cũ, rồi dán mã vào máy mới. Không cần tài khoản hay mật khẩu.','Make a code on the old device, then paste it on the new one. No account or password needed.')}</p>
 <div class="row"><button class="btn" data-act="mkcode">${t('Tạo mã của hồ sơ này','Make a code for this profile')}</button>${PF.code?`<button class="btn" data-act="copycode">${t('Sao chép mã','Copy the code')}</button>`:''}</div>
 ${PF.code?`<textarea class="field ta" readonly aria-label="${t('Mã chuyển máy','Transfer code')}">${PF.code}</textarea>`:''}
 <label class="lbl" for="code-in">${t('Có mã từ máy khác? Dán vào đây','Got a code from another device? Paste it here')}</label><textarea id="code-in" class="field ta" placeholder="MHT1…"></textarea>
 <div class="row"><button class="btn" data-act="usecode">${t('Nhập mã thành hồ sơ mới','Import as a new profile')}</button>${PF.msg?`<span class="pill bad">${PF.msg}</span>`:''}</div>`}

/* ============ BÁO CÁO + GIẤY KHEN ============ */
function vReport(){const who=S.name?esc(S.name):t('con','your child'),dn=doneN(),total=TOPICS.reduce((s,x)=>s+starN(S.best[bk(x.id)]||0),0),bestEx=S.exams.filter(e=>(e.lv||1)===lvOf()).reduce((m,e)=>Math.max(m,e.score),0);
 const nm=f=>TOPICS.filter(f).map(x=>tp(x).name).join(', ');
 const strong=nm(x=>(S.best[bk(x.id)]||0)>=80),weak=nm(x=>S.best[bk(x.id)]!=null&&S.best[bk(x.id)]<70),todo=nm(x=>S.best[bk(x.id)]==null);
 const tile=(v,l)=>`<div class="tile"><b>${v}</b><span>${l}</span></div>`,exs=S.exams.filter(e=>(e.lv||1)===lvOf()).reverse();
 return `<section class="card stack report"><div class="row" style="justify-content:space-between"><div><h2>${t('Báo cáo học tập của '+who,'Learning report for '+who)} · ${t('Cấp độ','Level')} ${lvOf()}</h2><p class="muted">${t('Ngày lập','Date')}: ${new Date().toLocaleDateString(en()?'en-GB':'vi-VN')}</p></div><div class="row noprint"><button class="btn" data-act="print">${t('In báo cáo','Print the report')}</button><a class="btn" href="#giay-khen">${t('Xem giấy khen','See the certificate')}</a></div></div>
 <div class="noprint">${levelBar()}</div>
 <div class="tiles">${tile(dn+'/'+TOPICS.length,t('chủ đề hoàn thành','topics done'))}${tile(total+'/'+TOPICS.length*3,t('sao','stars'))}${tile(S.maxStreak||0,t('ngày học liên tục dài nhất','longest streak in days'))}${tile(bestEx||'–',t('điểm thi thử cao nhất','best exam score'))}</div>
 <h3>${t('Kết quả luyện tập theo chủ đề','Practice results by topic')}</h3>
 <div class="rbars">${TOPICS.map(x=>{const b=S.best[bk(x.id)];return `<div class="rrow"><span class="rn">${tp(x).name}</span><div class="rbar"><i style="width:${b||0}%;background:${b>=80?'var(--ok)':b>=50?'var(--sun)':'var(--bad)'}"></i><em></em></div><span class="tnum rv">${b!=null?b+'%':'–'}</span></div>`}).join('')}</div>
 <p class="muted">${t('Vạch đứng là mốc 70%, mức để tính hoàn thành chủ đề. Xanh là từ 80%, vàng là 50 đến 79%, đỏ là dưới 50%.','The vertical line marks 70%, the level that counts a topic as done. Green is 80% or more, yellow 50 to 79%, red below 50%.')}</p>
 ${exs.length?`<h3>${t('Điểm các lần thi thử','Practice exam scores')}</h3><div class="excols">${exs.map(e=>`<div class="exc"><span class="tnum">${e.score}</span><i style="height:${Math.max(4,e.score/10)}px;background:${e.score>=800?'var(--ok)':'var(--blue)'}"></i><small>${esc(String(e.d).slice(0,5))}</small></div>`).join('')}</div><p class="muted">${t('Từ cũ đến mới. Cột xanh lá là lần đạt mục tiêu luyện tập 800 điểm.','Oldest to newest. Green columns reached the 800-point practice goal.')}</p>`:''}
 <h3>${t('Nhận xét','Summary')}</h3><ul class="lesson">
 ${strong?`<li><b>${t('Đã vững','Solid')}:</b> ${strong}.</li>`:''}${weak?`<li><b>${t('Cần ôn lại (dưới 70%)','Needs review (below 70%)')}:</b> ${weak}.</li>`:''}${todo?`<li><b>${t('Chưa luyện tập','Not practised yet')}:</b> ${todo}.</li>`:''}
 <li>${t(`Còn ${S.wrong.length} câu đang làm sai. Nút “Ôn câu em làm sai” ở trang chủ gom sẵn các câu này.`,`${S.wrong.length} questions are still missed. “Fix my mistakes” on the home page collects them.`)}</li>
 <li><b>${t('Việc nên làm tiếp','Next step')}:</b> ${mission().txt}.</li></ul>
 <p class="muted">${t('Tiến độ chỉ lưu trên trình duyệt của máy này. Muốn chuyển sang máy khác, dùng mã chuyển máy trong phần hồ sơ.','Progress is saved only in this browser. To move it to another device, use the transfer code in the profile panel.')}</p></section>`}

function vCert(){const NT=TOPICS.length,ok=doneN()>=NT,total=TOPICS.reduce((s,x)=>s+starN(S.best[bk(x.id)]||0),0),bestEx=S.exams.filter(e=>(e.lv||1)===lvOf()).reduce((m,e)=>Math.max(m,e.score),0);
 return `<div class="stack"><a class="back noprint" href="#trang-chu">← ${t('Về trang bài học','Back to lessons')}</a>
 <div class="noprint">${levelBar()}</div>
 ${ok?'':`<div class="tip noprint"><h3>${t('Giấy khen đang chờ em','Your certificate is waiting')}</h3><p>${t(`Giấy khen Cấp độ ${lvOf()} mở khi em hoàn thành cả ${NT} chủ đề của cấp độ này. Em đã xong ${doneN()}/${NT}. Bên dưới là bản xem trước.`,`The Level ${lvOf()} certificate unlocks when all ${NT} topics of this level are done. You have finished ${doneN()} of ${NT}. Below is a preview.`)}</p></div>`}
 <section class="cert ${ok?'':'locked'}">${CLOUD}
  <div class="ct">${t('GIẤY KHEN','CERTIFICATE')}</div>
  <div class="cs"><span>${t('Cấp độ','Level')} ${lvOf()} · ${t(LEVELS[lvOf()-1][1],LEVELS[lvOf()-1][2])}</span></div>
  <p>${t('Mây Học Tin vui mừng trao tặng bạn','Mây Học Tin is happy to present this to')}</p>
  <div class="cn">${S.name?esc(S.name):t('Bạn nhỏ','Our friend')}</div>
  <p>${t(`vì đã hoàn thành ${NT} chủ đề luyện tập Tin học Cấp độ ${lvOf()} trên Mây Học Tin`,`for finishing all ${NT} Level ${lvOf()} computing practice topics on Mây Học Tin`)}</p>
  <div class="cs"><span>${total}/${NT*3} ${t('sao','stars')}</span>${bestEx?`<span>${t('Thi thử cao nhất','Best practice exam')}: ${bestEx}/1000</span>`:''}<span>${S.badges.length} ${t('huy hiệu','badges')}</span></div>
  <p><b>${ok?esc((S.done||{})[lvOf()]||''):t('Ngày hoàn thành sẽ ghi ở đây','The finish date will appear here')}</b></p>
  <small>${t('Đây là giấy khen luyện tập của trang Mây Học Tin, không phải chứng chỉ IC3 Spark hay chứng chỉ của bất kỳ tổ chức thi nào.','This is a practice award from the Mây Học Tin site. It is not an IC3 Spark certificate or a certificate from any exam body.')}</small>
 </section>
 <div class="row noprint">${ok?`<button class="btn primary" data-act="print">${t('In giấy khen','Print the certificate')}</button>`:''}${S.name?'':`<span class="muted">${t('Em nhập tên trong phần hồ sơ để tên hiện trên giấy khen.','Add your name in the profile panel so it shows on the certificate.')}</span>`}</div>
 <p class="muted noprint">${t('Nếu bấm In mà không thấy gì, hãy mở trang ở bản đã cài trên điện thoại hoặc máy tính rồi in lại.','If Print does nothing, open the installed version of the site and print from there.')}</p></div>`}

/* ============ CẨM NANG KỲ THI (trang Phụ huynh) ============ */
function vGuide(){const li=a=>'<ul>'+a.map(v=>`<li>${v}</li>`).join('')+'</ul>',e=en();
 const map=e?[['Technology basics','Topics 1, 2, 3'],['Digital citizenship','Topic 10'],['Information management','Topic 7'],['Content creation','Topics 4, 6 (topic 5 is extra)'],['Communication','Topic 8'],['Collaboration','Topic 9'],['Safety and security','Topic 11']]:[['Căn bản về công nghệ','Chủ đề 1, 2, 3'],['Công dân số','Chủ đề 10'],['Quản lý thông tin','Chủ đề 7'],['Sáng tạo nội dung','Chủ đề 4, 6 (chủ đề 5 là phần mở rộng)'],['Truyền thông','Chủ đề 8'],['Cộng tác','Chủ đề 9'],['An toàn và bảo mật','Chủ đề 11']];
 const C=t('CĐ','T'),B=t('bài','lessons'),det=[
 [1,'Phần cứng và các thiết bị phần cứng','Hardware and hardware devices',`${C}1 ${B} 1, 2, 4, 8`],[1,'Phần mềm: khái niệm và phân loại','Software: concept and types',`${C}3 ${B} 1, 2, 7`],[1,'Phần cứng cơ bản','Basic hardware parts',`${C}1 ${B} 3, 5`],[1,'Chương trình ứng dụng trên máy tính để bàn','Desktop application programs',`${C}3 ${B} 2, 7`],[1,'Hệ điều hành','Operating system',`${C}2 ${B} 1, 2, 6, 7`],[1,'Tập tin và thư mục','Files and folders',`${C}2 ${B} 3, 4, 5`],[1,'Thiết bị di động','Mobile devices',`${C}1 ${B} 7`],[1,'Mạng và Internet','Networks and the Internet',`${C}7 ${B} 1, 7, 9`],
 [2,'Khái niệm công dân số','What digital citizenship is',`${C}10 ${B} 1`],[2,'Quyền công dân số','Digital citizenship rights',`${C}10 ${B} 2`],[2,'Chuẩn mực khi tương tác trực tuyến','Standards for interacting online',`${C}10 ${B} 5, 6`],[2,'Tính công cộng và lâu dài của Internet','The public and permanent nature of the Internet',`${C}10 ${B} 3, 4`],
 [3,'Khái niệm cơ bản: website, trang web, tìm kiếm','Basics: website, web page, searching',`${C}7 ${B} 4, 7`],[3,'Trình duyệt web','Web browsers',`${C}7 ${B} 2, 3, 5`],[3,'Xác định loại thông tin trên trang web','Identifying kinds of information on a page',`${C}7 ${B} 6, 8`],[3,'Lưu và đánh dấu trang web','Saving and bookmarking pages',`${C}7 ${B} 2`],
 [4,'Khái niệm cơ bản: tài liệu, phông, định dạng, hình, slide','Basics: document, font, formatting, picture, slide',`${C}4 ${B} 1, 2 · ${C}6 ${B} 1`],[4,'Microsoft Word','Microsoft Word',`${C}4 ${B} 1 → 6, 8`],[4,'Giới thiệu Microsoft PowerPoint','Introduction to Microsoft PowerPoint',`${C}6 ${B} 1 → 6`],[4,'Các phím đặc biệt trên bàn phím','Special keys on the keyboard',`${C}4 ${B} 1, 7 · ${t('trò chơi Gõ phím','the Typing game')}`],
 [5,'Khái niệm cơ bản: email, tin nhắn văn bản, tin nhắn tức thời','Basics: email, text messages, instant messages',`${C}8 ${B} 1, 2, 3, 5`],[5,'Các phương thức truyền thông','Ways of communicating',`${C}8 ${B} 4, 5, 7`],
 [6,'Chuẩn mực kỹ thuật số khi cộng tác','Digital etiquette for collaboration',`${C}9 ${B} 1 → 6`],
 [7,'Khái niệm cơ bản: bắt nạt trực tuyến, mật khẩu, dữ liệu cá nhân','Basics: cyberbullying, passwords, personal data',`${C}11 ${B} 1, 2, 4`],[7,'Bảo mật máy tính','Computer security',`${C}11 ${B} 3, 6, 7`],[7,'Sử dụng thiết bị an toàn','Using devices safely',`${C}11 ${B} 5, 6 · ${C}1 ${B} 6`],[7,'Ứng xử trực tuyến phù hợp','Appropriate behaviour online',`${C}10 ${B} 5, 6`]];
 return `<section class="card lesson"><h2>${t('Cẩm nang kỳ thi IC3 GS6 Spark','IC3 GS6 Spark exam guide')}</h2>
 <p>${t('Tổng hợp từ trang giới thiệu và tài liệu “Hướng dẫn dự thi IC3 GS6 Spark” của IIG Việt Nam. Quy định có thể thay đổi, ba mẹ nên xem lại nguồn chính thức trước khi đăng ký.','Summarised from IIG Vietnam’s exam page and its “IC3 GS6 Spark candidate guide”. Rules can change, so please check the official source before you register.')}</p>
 <h3>${t('Bài thi là gì?','What is the exam?')}</h3>
 ${li(e?['IC3 Spark is an international digital literacy certificate from Certiport (USA) for primary pupils. In Vietnam it is run by IIG Vietnam.','The current version is IC3 GS6 Spark, taken on a computer in Vietnamese.','IIG’s guide describes candidates as roughly 8 to 10 years old, grades 3 to 5.']:['IC3 Spark là chứng chỉ tin học quốc tế của Certiport (Hoa Kỳ) dành cho học sinh tiểu học, tại Việt Nam do IIG Việt Nam tổ chức.','Phiên bản đang triển khai là IC3 GS6 Spark, thi trên máy tính bằng tiếng Việt.','Tài liệu của IIG mô tả thí sinh khoảng 8 đến 10 tuổi, lớp 3 đến lớp 5.'])}
 <h3>${t('Ba cấp độ','Three levels')}</h3>
 ${li(e?['<b>Level 1 (Know)</b>: basic concepts and essential parts.','<b>Level 2 (Do)</b>: doing tasks with core applications and online.','<b>Level 3 (Lead)</b>: more advanced understanding.','Each level is its own exam with its own certificate.']:['<b>Level 1 (Know)</b>: khái niệm cơ bản và thành phần thiết yếu.','<b>Level 2 (Do)</b>: thực hành nhiệm vụ với các ứng dụng chủ chốt và trong môi trường trực tuyến.','<b>Level 3 (Lead)</b>: hiểu biết nâng cao hơn.','Mỗi cấp là một bài thi riêng, có chứng chỉ riêng.'])}
 <p>${t('Trên Mây Học Tin, mỗi chủ đề có bài học, câu luyện tập và bài thi thử riêng cho từng cấp độ. Con chọn cấp độ ở đầu trang Bài học. Nên học theo thứ tự: xong Cấp độ 1 rồi mới sang Cấp độ 2 và 3.','On Mây Học Tin every topic has its own lessons, practice questions and practice exam for each level. Your child picks the level at the top of the Lessons page. It is best to go in order: finish Level 1 before Levels 2 and 3.')}</p>
 <p class="muted">${t('Cấp độ 1 bám theo đề cương 7 chuyên đề của IIG. Cấp độ 2 và 3 được soạn theo bảng mục tiêu IC3 GS6 Level 2 và Level 3 công khai (bản dành cho học sinh lớn hơn), viết lại ở mức tiểu học, vì bảng mục tiêu riêng của bản Spark chưa đọc được. Vì vậy hai cấp này có thể chưa khớp hoàn toàn với đề thi Spark.','Level 1 follows IIG’s 7-domain outline. Levels 2 and 3 are written from the public IC3 GS6 Level 2 and Level 3 objectives (the edition for older students), rewritten for primary pupils, because the Spark-specific objective sheets could not be read. These two levels may therefore not match the Spark exam exactly.')}</p>
 <h3>${t('7 chuyên đề và chủ đề tương ứng trên Mây Học Tin','The 7 domains and where they are on Mây Học Tin')}</h3>
 <div class="tablebox"><table class="t"><tr><th>${t('Chuyên đề của bài thi','Exam domain')}</th><th>${t('Học ở đâu trên trang','Where to study it here')}</th></tr>${map.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</table></div>
 <h3>${t('Đối chiếu từng dòng với đề cương IC3 GS6 Spark','Line-by-line check against the IC3 GS6 Spark outline')}</h3>
 <div class="tablebox"><table class="t"><tr><th>${t('Chuyên đề','Domain')}</th><th>${t('Nội dung trong đề cương','Outline item')}</th><th>${t('Học ở đâu trên trang','Where on this site')}</th></tr>${det.map(r=>`<tr><td class="tnum">${r[0]}</td><td>${t(r[1],r[2])}</td><td>${r[3]}</td></tr>`).join('')}</table></div>
 <p class="muted">${t('Đề cương ở đây là danh sách nội dung 7 chuyên đề do IIG Việt Nam công bố. Bảng mục tiêu gốc của Certiport cho GS6 Spark không đọc tự động được, nên các bài còn được soạn sâu thêm theo bảng mục tiêu IC3 GS6 Level 1 công khai, ở mức phù hợp với học sinh tiểu học.','The outline here is the 7-domain content list published by IIG Vietnam. Certiport’s own objective sheet for GS6 Spark could not be read automatically, so lessons also draw on the public IC3 GS6 Level 1 objectives, at a level suited to primary pupils.')}</p>
 <p class="muted">${t('Phần Sáng tạo nội dung trong danh sách của IIG nêu Word và PowerPoint, không nêu Excel. Chủ đề 5 (Bảng tính) vẫn được giữ như phần mở rộng vì trẻ sẽ gặp ở cấp học sau, và bài thi thử chỉ lấy 1 câu của chủ đề này.','IIG’s list for Content creation names Word and PowerPoint, not Excel. Topic 5 (Spreadsheets) stays as an extra because children meet it in later grades, and the practice exam takes only 1 question from it.')}</p>
 <h3>${t('Cấu trúc bài thi','Exam format')}</h3>
 ${li(e?['Time: <b>50 minutes</b>.','Questions: <b>31</b> at Level 1, <b>36</b> at Level 2, <b>42</b> at Level 3.','Pass mark: <b>700 out of 1000</b>.','Question types shown in the guide: drag and drop, typing an answer, and Yes/No.','The score appears as soon as the exam is handed in.']:['Thời gian làm bài: <b>50 phút</b>.','Số câu hỏi: <b>31</b> câu ở Level 1, <b>36</b> câu ở Level 2, <b>42</b> câu ở Level 3.','Điểm đạt: <b>700/1000</b>.','Dạng câu hỏi được minh hoạ trong tài liệu: kéo thả, nhập câu trả lời và Yes/No.','Thí sinh biết điểm ngay sau khi nộp bài.'])}
 <p class="muted">${t('Bảng cấu trúc trong tài liệu dùng ô gộp nên khi đọc tự động không tách chắc được từng ô. Cách đọc ở trên (50 phút và 700/1000 áp dụng cho cả ba cấp) là cách hợp lý nhất, ba mẹ nên hỏi lại IIG để chắc chắn. Phòng thi thử của trang dựng theo từng cấp: 31, 36 và 42 câu trong 50 phút.','The format table in the guide uses merged cells, so an automatic reading cannot separate every cell with certainty. The reading above (50 minutes and 700/1000 for all three levels) is the most likely one; please confirm with IIG. The exam room here follows each level: 31, 36 and 42 questions in 50 minutes.')}</p>
 <h3>${t('Màn hình làm bài','The exam screen')}</h3>
 ${li(e?['A countdown clock at the top right.','Next and Back buttons. Both save the current answer.','Reset: clears only the current question. The clock keeps running.','Mark for review: flag a question to come back to.','Go to Summary: see which questions are answered, unanswered or marked.','Finish Exam, then Submit, to hand in.']:['Đồng hồ đếm ngược ở góc trên bên phải.','Nút sang câu sau và quay lại câu trước. Cả hai đều lưu câu trả lời.','Cài đặt lại câu hỏi: chỉ xoá câu đang làm, đồng hồ vẫn chạy.','Đánh dấu để xem lại: gắn cờ câu chưa chắc để quay lại sau.','Go to Summary: xem câu nào đã làm, chưa làm, đã đánh dấu.','Finish Exam rồi Submit để nộp bài.'])}
 <p class="muted">${t('Phòng thi thử của trang có đủ các chức năng tương ứng: đồng hồ, câu trước, câu sau, làm lại câu này, đánh dấu xem lại, bảng số câu và nộp bài.','The exam room here has the matching controls: clock, previous, next, reset this question, mark for review, the question grid and hand in.')}</p>
 <h3>${t('Nếu chưa đạt, khi nào được thi lại?','If your child does not pass, when can they retake?')}</h3>
 ${li(e?['After the first attempt: wait at least <b>24 hours</b>.','After two failed attempts in a row: wait at least <b>48 hours</b>.','There is no limit on the number of attempts in a year.']:['Sau lần thi đầu chưa đạt: chờ ít nhất <b>24 giờ</b>.','Sau hai lần liên tiếp chưa đạt: chờ ít nhất <b>48 giờ</b>.','Không giới hạn số lần thi trong một năm.'])}
 <h3>${t('Đăng ký và giấy tờ','Registering and ID papers')}</h3>
 ${li(e?['Parents register online on IIG Vietnam’s site. In Ho Chi Minh City, registration goes through the city’s Department of Education and Training.','Accepted ID: national ID card or passport. A child too young for these brings a copy of the birth certificate plus a photo confirmation form from IIG.','Papers must be originals on paper, valid and clearly readable.','Without valid ID on the day, the child cannot sit the exam and the fee is not refunded.']:['Phụ huynh đăng ký trực tuyến trên trang của IIG Việt Nam. Tại TP.HCM, thí sinh đăng ký qua Sở GD&ĐT.','Giấy tờ hợp lệ: căn cước hoặc hộ chiếu. Trẻ chưa đủ tuổi làm các giấy tờ này mang bản sao giấy khai sinh kèm Giấy xác nhận có ảnh theo mẫu của IIG.','Giấy tờ phải là bản giấy, còn hạn, rõ nét.','Thiếu giấy tờ hợp lệ vào ngày thi thì không được thi và không được hoàn lệ phí.'])}
 <h3>${t('Nội quy và tình huống bất ngờ','Rules and unexpected situations')}</h3>
 ${li(e?['Arrive on time, dress neatly, put belongings away and follow the supervisor.','No cheating, no sharing answers, and no discussing the questions after the exam. Breaking the rules can cancel the result and lead to a suspension of 1 to 2 years.','Illness or an accident with proof: the fee is kept and the session moved at no charge.','A system fault during the exam: the child retakes at no charge.']:['Đến đúng giờ, trang phục lịch sự, cất tư trang và làm theo hướng dẫn của giám thị.','Không gian lận, không trao đổi đáp án, không bàn luận hay phát tán đề sau khi thi. Vi phạm có thể bị huỷ bài và đình chỉ thi 1 đến 2 năm.','Ốm hoặc tai nạn có minh chứng: được bảo lưu lệ phí và chuyển buổi thi miễn phí.','Lỗi hệ thống khi đang thi: được thi lại không mất phí.'])}
 <h3>${t('Kết quả và chứng chỉ','Results and certificate')}</h3>
 ${li(e?['On exam day the child gets a Certiport account, used to sit the exam and to look up results.','In the account, My Transcript holds the score report and the online certificate, which you can print yourself.','Each certificate carries a verification code (CIC) that anyone can check on Certiport’s site without logging in.','IIG states that the online certificate does not expire.']:['Ngày thi, thí sinh được cấp tài khoản Certiport để làm bài và tra cứu kết quả.','Trong tài khoản, mục My Transcript có phiếu điểm và chứng chỉ online, ba mẹ tự in được.','Mỗi chứng chỉ có mã xác thực (CIC), ai cũng kiểm tra được trên trang của Certiport mà không cần đăng nhập.','IIG cho biết chứng chỉ online dùng được vĩnh viễn.'])}
 <h3>${t('Công cụ ôn luyện chính thức và nguồn tham khảo','Official practice tools and sources')}</h3>
 ${li(e?['IIG Vietnam offers the GMetrix IC3 Spark practice software from Certiport (paid) and its own online learning platform.','Mây Học Tin is a free companion for learning and practice. It does not replace the official practice software.','Exam fees, dates and venues are not in the documents above. Please ask IIG Vietnam or the school.']:['IIG Việt Nam có phần mềm luyện thi GMetrix IC3 Spark của Certiport (có phí) và nền tảng học trực tuyến riêng.','Mây Học Tin là trang học và luyện tập miễn phí để hỗ trợ thêm, không thay thế phần mềm luyện thi chính thức.','Lệ phí, lịch thi và địa điểm thi không có trong các tài liệu trên. Ba mẹ hỏi IIG Việt Nam hoặc nhà trường.'])}
 <p><a class="back" href="https://iigvietnam.com/bai-thi-ic3-spark/">${t('Trang bài thi IC3 Spark của IIG Việt Nam','IIG Vietnam’s IC3 Spark page')}</a><br><a class="back" href="https://iigvietnam.com/wp-content/uploads/2025/06/H%C6%B0%E1%BB%9Bng%20d%E1%BA%ABn%20d%E1%BB%B1%20thi%20IC3%20GS6%20Spark.pdf">${t('Hướng dẫn dự thi IC3 GS6 Spark (PDF của IIG)','IC3 GS6 Spark candidate guide (IIG PDF)')}</a></p>
 </section>`}

/* ---- hoạt động cho Cộng tác, Công dân số, Bảng tính ---- */
LWR.perm=()=>{const s=ls('perm',{i:0}),P=[[t('Xem','View'),1,0,0],[t('Nhận xét','Comment'),1,1,0],[t('Chỉnh sửa','Edit'),1,1,1]],A=[t('Đọc bài','Read the work'),t('Để lại nhận xét','Leave comments'),t('Sửa nội dung','Change the content')];
 return `<p>${t('Em bấm Share và chọn quyền cho bạn. Xem bạn làm được gì với từng quyền.','You click Share and choose a permission. See what a friend can do with each one.')}</p><div class="chips">${P.map((p,i)=>lb('perm',i,p[0],s.i===i?'sel':'')).join('')}</div><div class="chips">${A.map((a,k)=>`<span class="pill ${P[s.i][k+1]?'ok':'none'}">${P[s.i][k+1]?'✓':'✕'} ${a}</span>`).join('')}</div><p class="msg">${[t('Xem: hợp khi em chỉ muốn bạn đọc.','View: good when you only want a friend to read.'),t('Nhận xét: hợp khi em muốn bạn góp ý mà không đổi bài.','Comment: good when you want suggestions without changes to the text.'),t('Chỉnh sửa: hợp khi cả nhóm cùng viết. Chỉ cấp cho người em tin tưởng.','Edit: good when the group writes together. Give it only to people you trust.')][s.i]}</p>`};
LWA.perm=v=>{ls('perm',{i:0}).i=+v};
LWR.meet=()=>{const s=ls('meet',{mic:1,cam:1,hand:0});
 const m=s.hand&&!s.mic?t('Em đã giơ tay và tắt micro. Rất lịch sự. Chờ thầy cô mời rồi bật micro để nói.','Hand raised and microphone muted. Very polite. Wait to be invited, then unmute to speak.'):s.mic?t('Micro đang bật: cả lớp nghe thấy tiếng ồn quanh em. Khi không nói, em hãy tắt micro.','Your microphone is on, so the class hears the noise around you. Mute it when you are not speaking.'):t('Micro đã tắt. Muốn phát biểu, em bấm giơ tay.','Microphone muted. To speak, press raise hand.');
 return `<p>${t('Em đang trong một buổi học trực tuyến và thầy cô đang giảng. Chỉnh các nút cho đúng phép lịch sự.','You are in an online lesson and the teacher is talking. Set the buttons the polite way.')}</p><div class="chips">${lb('meet','mic',(s.mic?t('Micro: đang bật','Microphone: on'):t('Micro: đã tắt','Microphone: muted')),s.mic?'sel':'')}${lb('meet','cam',(s.cam?t('Camera: đang bật','Camera: on'):t('Camera: đã tắt','Camera: off')),s.cam?'sel':'')}${lb('meet','hand',(s.hand?t('Đang giơ tay','Hand raised'):t('Giơ tay','Raise hand')),s.hand?'sel':'')}</div><p class="msg">${m}</p>${s.cam?'':`<p class="muted">${t('Nếu thầy cô yêu cầu bật camera thì em bật lên nhé.','If the teacher asks for cameras on, turn yours on.')}</p>`}`};
LWA.meet=v=>{const s=ls('meet',{mic:1,cam:1,hand:0});s[v]=s[v]?0:1};
const POSTS=[['Ảnh con mèo nhà em đang ngủ','A photo of your cat asleep',1,'Không lộ thông tin riêng và không làm ai buồn.','It gives away nothing private and hurts nobody.'],['Ảnh thẻ học sinh có họ tên, lớp và trường','A photo of your school card with your name, class and school',0,'Lộ thông tin nhận dạng cá nhân của em.','It shows your personally identifiable information.'],['Lời chê một bạn trong lớp vẽ xấu','A comment saying a classmate draws badly',0,'Không tử tế, và bạn ấy có thể rất buồn.','It is unkind and could really upset them.'],['Bức tranh em tự vẽ','A picture you drew yourself',1,'Đây là sản phẩm của chính em.','It is your own work.'],['Ảnh bạn thân đang ngủ gật, chưa hỏi ý bạn','A photo of your friend dozing off, without asking them',0,'Em cần hỏi ý bạn trước khi đăng ảnh của bạn.','You need to ask a friend before posting their photo.']];
LWR.post=()=>{const s=ls('post',{a:{}});return `<p>${t('Với mỗi bài, em chọn Đăng hay Không đăng.','For each post, choose Post or Do not post.')}</p>${POSTS.map((p,i)=>{const c=s.a[i];return `<div class="srow"><span>${t(p[0],p[1])}</span><div class="chips">${lb('post',i+':1',t('Đăng','Post'),c===1?'sel':'')}${lb('post',i+':0',t('Không đăng','Do not post'),c===0?'sel':'')}</div>${c==null?'':`<p class="msg" style="flex:1 1 100%"><span class="pill ${c===p[2]?'ok':'bad'}">${c===p[2]?t('Đúng','Right'):t('Nghĩ lại nhé','Think again')}</span> ${t(p[3],p[4])}</p>`}</div>`}).join('')}`};
LWA.post=v=>{const [i,c]=v.split(':');ls('post',{a:{}}).a[+i]=+c};
LWR.fill=()=>{const s=ls('fill',{k:0,n:1}),K=[[t('Dãy số','Number series'),['1','2','3','4','5','6']],[t('Thứ trong tuần','Days of the week'),en()?['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']:['Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy']],[t('Công thức','Formula'),['=A1*2','=A2*2','=A3*2','=A4*2','=A5*2','=A6*2']]],base=s.k===0?2:1,shown=Math.max(base,s.n);
 return `<p>${t('Chọn một kiểu dữ liệu rồi bấm kéo nút điền xuống.','Pick a kind of data, then drag the fill handle down.')}</p><div class="chips">${K.map((k,i)=>lb('fill','k'+i,k[0],s.k===i?'sel':'')).join('')}</div><div class="sim"><table class="xl"><tr><th></th><th>B</th></tr>${K[s.k][1].map((v,i)=>`<tr><th>${i+1}</th><td><span class="cell ${i<base?'hl':''}">${i<shown?v:''}</span></td></tr>`).join('')}</table></div><div class="chips">${lb('fill','go',t('Kéo nút điền xuống một ô','Drag the fill handle down one cell'),'',shown>=6)}${lb('fill','re',t('Làm lại','Reset'))}</div><p class="msg">${[t('Excel thấy quy luật tăng 1 nên điền tiếp 3, 4, 5.','Excel sees the pattern of adding 1 and continues with 3, 4, 5.'),t('Excel biết thứ tự các ngày trong tuần nên tự điền tiếp.','Excel knows the order of the days and fills in the next ones.'),t('Công thức được chép xuống và địa chỉ ô tự đổi theo từng hàng: A1 thành A2, A3.','The formula is copied down and the cell address changes with each row: A1 becomes A2, A3.')][s.k]}</p>`};
LWA.fill=v=>{const s=ls('fill',{k:0,n:1});if(v[0]==='k'){s.k=+v[1];s.n=1}else if(v==='go')s.n=Math.max(s.k===0?2:1,s.n)+1;else s.n=1};
